-- ----------------------------
-- Table structure for account
-- ----------------------------
DROP TABLE IF EXISTS `account`;
CREATE TABLE `account`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `owner_type` tinyint NOT NULL DEFAULT 1 COMMENT '1个人 2家庭',
  `user_id` bigint NOT NULL COMMENT '归属用户',
  `family_id` bigint NULL DEFAULT NULL COMMENT '家庭ID',
  `creator_id` bigint NOT NULL COMMENT '创建人',
  `belong_member_id` bigint NULL DEFAULT NULL COMMENT '归属成员(family_member.id)',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '账户名称',
  `type` tinyint NOT NULL DEFAULT 1 COMMENT '1现金 2储蓄卡 3信用卡 4虚拟',
  `icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '图标',
  `init_balance` bigint NOT NULL DEFAULT 0 COMMENT '用户填写的初始余额(分)',
  `balance` bigint NOT NULL DEFAULT 0 COMMENT '记账推算余额(分),非真实资金',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `include_in_total` tinyint NOT NULL DEFAULT 1 COMMENT '计入记账口径总资产',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_family_id`(`family_id` ASC) USING BTREE,
  INDEX `idx_belong_member`(`belong_member_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '账户表' ROW_FORMAT = Dynamic;

