-- ----------------------------
-- Table structure for bill
-- ----------------------------
DROP TABLE IF EXISTS `bill`;
CREATE TABLE `bill`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `owner_type` tinyint NOT NULL DEFAULT 1 COMMENT '1个人 2家庭',
  `user_id` bigint NOT NULL COMMENT '归属用户',
  `family_id` bigint NULL DEFAULT NULL COMMENT '家庭ID',
  `creator_id` bigint NOT NULL COMMENT '记账人(user_id或family_member.id)',
  `member_id` bigint NULL DEFAULT NULL COMMENT '为谁花的(family_member.id)',
  `book_id` bigint NOT NULL COMMENT '所属账本',
  `account_id` bigint NOT NULL COMMENT '账户',
  `to_account_id` bigint NULL DEFAULT NULL COMMENT '转入账户(仅记录转账用)',
  `category_id` bigint NULL DEFAULT NULL COMMENT '分类',
  `type` tinyint NOT NULL COMMENT '1支出 2收入 3转账',
  `amount` bigint NOT NULL COMMENT '金额(分)',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'CNY' COMMENT '币种',
  `happened_at` datetime NOT NULL COMMENT '账单发生时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `tags` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '标签(逗号分隔)',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '图片',
  `is_excluded` tinyint NOT NULL DEFAULT 0 COMMENT '不计入统计',
  `source` tinyint NOT NULL DEFAULT 1 COMMENT '来源:1手动 2CSV导入 3AI 4模板',
  `fingerprint` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'CSV 导入去重指纹',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_time`(`user_id` ASC, `happened_at` ASC) USING BTREE,
  INDEX `idx_family_time`(`family_id` ASC, `happened_at` ASC) USING BTREE,
  INDEX `idx_book_time`(`book_id` ASC, `happened_at` ASC) USING BTREE,
  INDEX `idx_user_cat`(`user_id` ASC, `category_id` ASC) USING BTREE,
  INDEX `idx_account`(`account_id` ASC) USING BTREE,
  INDEX `idx_creator`(`creator_id` ASC) USING BTREE,
  INDEX `idx_member`(`member_id` ASC) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE,
  INDEX `idx_deleted_time`(`deleted` ASC, `happened_at` ASC) USING BTREE,
  INDEX `idx_fingerprint`(`user_id` ASC, `fingerprint` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 223 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '账单表' ROW_FORMAT = Dynamic;

