-- ----------------------------
-- Table structure for bill_template
-- ----------------------------
DROP TABLE IF EXISTS `bill_template`;
CREATE TABLE `bill_template`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '模板名称',
  `type` tinyint NOT NULL DEFAULT 1 COMMENT '1支出 2收入 3转账',
  `amount` bigint NULL DEFAULT NULL COMMENT '默认金额(分)',
  `category_id` bigint NULL DEFAULT NULL COMMENT '默认分类',
  `account_id` bigint NULL DEFAULT NULL COMMENT '默认账户',
  `book_id` bigint NULL DEFAULT NULL COMMENT '默认账本',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '默认备注',
  `use_count` int NOT NULL DEFAULT 0 COMMENT '使用次数',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '快捷记账模板表' ROW_FORMAT = Dynamic;

